INSERT INTO metric_artifact VALUES(1027,962,40,'konversiya-lid-sdelka/konversiya_kval_lid_naznachennaya_vstrecha',NULL,2010.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Скольким подходящим клиентам интересно с нами встретиться?');
INSERT INTO metric_artifact VALUES(1028,963,40,'konversiya-lid-sdelka/dohodimost_do_pervoy_vstrechi',NULL,2020.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Сколько назначенных встреч действительно проходят?');
INSERT INTO metric_artifact VALUES(1029,540,40,'konversiya-lid-sdelka/konversiya_vstrecha_kp',NULL,300.0,NULL,NULL,NULL,0,'component',NULL,NULL,NULL,'Сколько встреч доходят до коммерческого предложения?');
INSERT INTO metric_artifact VALUES(1030,964,40,'konversiya-lid-sdelka/dolya_pervyh_vstrech_s_lpr',NULL,3010.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Как часто на первой встрече есть тот, кто принимает решение?');
INSERT INTO metric_artifact VALUES(1031,965,40,'konversiya-lid-sdelka/dolya_pervyh_vstrech_s_klientami_ne_po_profilyu',NULL,3020.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Сколько встреч оказываются с неподходящими клиентами?');
INSERT INTO metric_artifact VALUES(1032,541,40,'konversiya-lid-sdelka/konversiya_kp_sdelka',NULL,400.0,NULL,NULL,NULL,0,'component',NULL,NULL,NULL,'Сколько предложений клиенты принимают?');
INSERT INTO metric_artifact VALUES(1033,966,40,'konversiya-lid-sdelka/dolya_kp_posle_kotoryh_s_klientom_svyazalis',NULL,4010.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Как часто мы сами связываемся с клиентом после КП?');
INSERT INTO metric_artifact VALUES(1034,967,40,'konversiya-lid-sdelka/srednyaya_skidka_v_pervoy_versii_kp',NULL,4020.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Сколько мы скидываем в первом предложении?');
INSERT INTO metric_artifact VALUES(1035,548,40,'konversiya-lid-sdelka/vremya_podgotovki_kp',NULL,4030.0,NULL,NULL,NULL,0,'driver',NULL,NULL,NULL,'Как быстро мы присылаем предложение?');
INSERT INTO dimension VALUES(1,'Статья','Состав самой суммы: из каких доходов или расходов она собралась','Учётная система, если статьи размечены','Список свой у каждой суммы: строки, из которых собрана именно она. У «Доходов» это выручка и прочие доходы, у «Расходов» — семь групп');
INSERT INTO dimension VALUES(2,'Направление бизнеса','Вид деятельности или отдельный бизнес внутри компании: розница и опт, производство и услуги, продукт и сервис','Учётная система, если направления размечены','розница · опт · производство · услуги · подписка · аренда. Набор свой у каждой компании');
INSERT INTO dimension VALUES(3,'Юридическое лицо','По какому юрлицу или ИП группы проходит операция','Учётная система, реквизиты документа','Юрлица и ИП, через которые компания ведёт деятельность');
INSERT INTO dimension VALUES(4,'Бренд','Торговая марка, под которой продаётся товар или услуга','Номенклатурный справочник','Торговые марки, под которыми компания продаёт');
INSERT INTO dimension VALUES(5,'Канал продаж','Сайт, маркетплейсы, розничные точки, опт, отдел продаж, агрегаторы','Отчёт о продажах с признаком канала','собственный сайт · маркетплейсы · розничные точки · опт · отдел продаж · агрегаторы · соцсети');
INSERT INTO dimension VALUES(6,'Канал привлечения','Откуда пришёл клиент или заявка: реклама, органический поиск, соцсети, рассылки, прямые заходы, переходы с других сайтов, холодный обзвон, выставки, рекомендации. Идёт в паре с «Источником привлечения», который называет конкретный источник внутри канала','Система веб-аналитики, UTM-метки','платная реклама · органический поиск · соцсети · рассылки · прямые заходы · переходы с других сайтов · холодный обзвон · выставки · рекомендации');
INSERT INTO dimension VALUES(7,'Товарная категория','Группа товаров или услуг на том уровне, где компания принимает решения по ассортименту. Отдельная позиция — разрез «Продукт»','Номенклатурный справочник','Группы товаров и услуг из номенклатуры компании. Уровень группировки компания выбирает свой');
INSERT INTO dimension VALUES(8,'Новый или повторный','Клиент покупает впервые или возвращается','CRM или учётная система по истории покупок','новый · повторный');
INSERT INTO dimension VALUES(9,'Размер клиента','Крупные, средние, мелкие по обороту или по сумме сделки','Отчёт о продажах в разрезе клиентов','крупный · средний · малый. Границы каждая компания задаёт свои — по обороту или по сумме сделки');
INSERT INTO dimension VALUES(10,'Тип клиента','Юридическое лицо или физическое','CRM, признак в карточке клиента','юридическое лицо · физическое лицо · ИП');
INSERT INTO dimension VALUES(11,'Отрасль клиента','Сфера, в которой работает клиент: ритейл, производство, услуги, госсектор, ИТ','CRM, признак в карточке клиента','ритейл · производство · услуги · госсектор · ИТ · строительство · медицина · образование');
INSERT INTO dimension VALUES(12,'География','Территория, на которой идёт работа. Уровень выбирает компания: страна, область, город, район','Адрес доставки или точки','Территории, на которых компания работает. Уровень выбирает компания: страна, область, город, район, улица');
INSERT INTO dimension VALUES(13,'Подразделение','Организационная единица: отдел, служба, филиал. Физические объекты разведены разрезами «Точка продаж», «Склад» и «Цех»','Учётная система с разметкой по подразделениям','Отделы, службы и филиалы компании. Физические объекты — отдельные разрезы **Точка продаж**, **Склад**, **Цех**');
INSERT INTO dimension VALUES(14,'Формат точки','Тип торговой точки: островок в торговом центре, отдельный магазин, киоск, окно выдачи, пункт выдачи','Реестр точек с признаком формата','островок в торговом центре · отдельный магазин · киоск · окно выдачи · пункт выдачи');
INSERT INTO dimension VALUES(15,'Сотрудник','Менеджер, продавец, исполнитель, бригада','Расчётная ведомость, CRM','Менеджеры, продавцы, исполнители и бригады компании');
INSERT INTO dimension VALUES(16,'Проект или заказ','Конкретная сделка, заказ, проект, партия выпуска','Учёт по заказам','Сделки, заказы, проекты и партии выпуска компании');
INSERT INTO dimension VALUES(17,'Контрагент','Конкретная сторона договора: название поставщика, подрядчика, банка, арендодателя','Договоры, накладные, акты','Юрлица и ИП, с которыми есть договорные отношения: поставщики, подрядчики, перевозчики, банки, арендодатели. Какая у стороны роль — отдельный разрез **Тип контрагента**');
INSERT INTO dimension VALUES(18,'Тип контрагента','Роль стороны в отношениях: поставщик, подрядчик, перевозчик, клиент, банк, арендодатель, страховщик','Справочник контрагентов с разметкой ролей','поставщик · подрядчик · перевозчик · клиент · банк · арендодатель · страховщик');
INSERT INTO dimension VALUES(20,'Валюта','Доллар, юань, евро и другие валюты расчётов','Выписка по валютным счетам, договоры в валюте','рубль · доллар · евро · юань и другие валюты расчётов компании');
INSERT INTO dimension VALUES(21,'Срок договора','На какой срок размещены или привлечены деньги: до востребования, до года, дольше года','Договоры вкладов, кредитов, займов, лизинга','до востребования · до года · от года до трёх · дольше трёх лет');
INSERT INTO dimension VALUES(22,'Тип затрат','Постоянные и переменные','Разметка статей вручную, один раз','постоянные · переменные');
INSERT INTO dimension VALUES(23,'Способ оплаты','Карты, быстрые платежи, наличные, рассрочка, безналичный перевод, оплата при получении. Заказ, который оплачивают курьеру или в пункте выдачи, относится к оплате при получении, даже если платят картой','Отчёты эквайера, платёжных сервисов и служб доставки','карта · быстрые платежи · наличные · рассрочка · безналичный перевод · кредит · оплата при получении');
INSERT INTO dimension VALUES(24,'Объект имущества','Здание, оборудование, транспорт, программа','Учёт основных средств','Здания, оборудование, транспорт и программы на балансе компании');
INSERT INTO dimension VALUES(25,'Продукт','Отдельная позиция прайса: товар или услуга. Идёт в паре с «Товарной категорией» там, где разбор по группе слишком крупный','Номенклатурный справочник','Позиции прайса компании. Варианты позиции (цвет, размер) — отдельный разрез **Вариант товара**');
INSERT INTO dimension VALUES(26,'Точка продаж','Конкретный магазин, островок, киоск, пункт выдачи. Тип точки — отдельный разрез «Формат точки»','Реестр точек, отчёт о продажах по точкам','Магазины, островки, киоски и пункты выдачи компании');
INSERT INTO dimension VALUES(27,'Склад','Конкретный склад хранения: свой, арендованный, склад площадки','Учёт остатков и движений по складам','Склады хранения: свои, арендованные, склады площадок');
INSERT INTO dimension VALUES(28,'Цех','Конкретный производственный участок или линия','Производственный учёт по участкам','Производственные участки и линии компании');
INSERT INTO dimension VALUES(29,'Тариф','Тарифный план, на котором сидит клиент. На какой срок он платит — отдельный разрез **Период оплаты подписки**','Биллинг, справочник тарифов','начальный · продвинутый · корпоративный · индивидуальный. Названия свои у каждой компании');
INSERT INTO dimension VALUES(30,'Механика акции','Чем сделана акция: скидка на полке, второй товар в подарок, промокод, списание бонусов, подарок за покупку','Календарь промо, отчёт по акциям','скидка на полке · второй товар в подарок · промокод · списание бонусов · подарок за покупку');
INSERT INTO dimension VALUES(31,'Способ получения','Как заказ попадает к покупателю: курьер, пункт выдачи, постамат, самовывоз из магазина','Отчёт о заказах с признаком доставки','курьер · пункт выдачи · постамат · самовывоз из магазина');
INSERT INTO dimension VALUES(32,'Устройство','Класс железа, с которого зашли. Операционная система — отдельный разрез **Платформа**, браузер против приложения — **Веб или приложение**','Система веб-аналитики, признак в заказе','десктоп · мобильный · планшет · умный ТВ');
INSERT INTO dimension VALUES(33,'Ценовой сегмент','Ценовой уровень позиции внутри категории: эконом, средний, премиум','Номенклатурный справочник с разметкой сегмента','эконом · средний · премиум');
INSERT INTO dimension VALUES(34,'Страница входа','Адрес страницы, с которой начался визит. Страница, где произошло событие, — отдельный разрез **Страница сайта**','Система веб-аналитики, отчёт по страницам входа','Адреса страниц, с которых начинаются визиты. У визита она ровно одна');
INSERT INTO dimension VALUES(35,'Календарный месяц','Месяц года как повторяющийся признак: все январи против всех июлей. Сезонность спроса, закупок и запасов','Учётная система, дата операции','январь … декабрь. Смотрятся как повторяющийся признак: все январи против всех июлей');
INSERT INTO dimension VALUES(36,'День недели','День недели как повторяющийся признак: будни против выходных','Учётная система, дата операции','понедельник … воскресенье. Будни против выходных');
INSERT INTO dimension VALUES(37,'Час суток','Час или интервал дня: утро, день, вечер, ночь. Часы пик и графики смен','Кассовые чеки с временем, веб-аналитика','Часы или интервалы дня: утро · день · вечер · ночь');
INSERT INTO dimension VALUES(38,'Источник привлечения','Конкретный источник внутри канала привлечения: рекламный сервис, поисковая система, отдельная рассылка, конкретная выставка или партнёр. Идёт в паре с «Каналом привлечения» — там, где разбор по каналу слишком крупный и бюджет распределяется внутри него',NULL,'Конкретные рекламные сервисы, поисковые системы, отдельные рассылки, выставки и партнёры внутри канала');
INSERT INTO dimension VALUES(39,'Вид материала','Группа закупаемого сырья, материалов и комплектующих: металл, пластик, ткань, упаковка, расходники. Не путать с «Товарной категорией»: та про то, что продаём, а этот про то, что закупаем',NULL,'металл · пластик · ткань · дерево · упаковка · расходники · комплектующие');
INSERT INTO dimension VALUES(40,'Причина возврата','Почему клиент вернул полученный товар','Заявки на возврат, акты приёмки','не подошёл размер · не совпало с описанием · брак · повреждён при доставке · передумал · привезли не то');
INSERT INTO dimension VALUES(41,'Причина отмены заказа','Почему заказ отменён до отгрузки','Статусы заказов в учётной системе','нет товара · не прошла оплата · передумал клиент · долгий срок доставки · дубль заказа');
INSERT INTO dimension VALUES(42,'Причина списания','Почему товар списан или не найден при инвентаризации','Акты списания, ведомости инвентаризации','истёк срок годности · повреждение при хранении · потеря товарного вида · неликвид · бой при обработке · кража · пересорт');
INSERT INTO dimension VALUES(43,'Причина брака','Из-за чего возник дефект','Акты о браке, рекламации, производственный учёт','сырьё · наладка оборудования · ошибка оператора · конструктив узла · условия эксплуатации');
INSERT INTO dimension VALUES(44,'Основание санкции','За что начислен штраф, пеня или неустойка — своя или выставленная контрагенту','Претензии, акты, требования госорганов','срыв срока · недопоставка · порча груза · ошибка в документах · просрочка оплаты · нарушение требований');
INSERT INTO dimension VALUES(45,'Причина невыкупа','Почему клиент отказался от заказа при вручении','Статусы доставки, отчёты перевозчика и площадки','не дождался · передумал до вручения · повреждена упаковка · не устроил срок · не было денег');
INSERT INTO dimension VALUES(46,'Период оплаты подписки','На какой срок клиент оплачивает подписку. Тарифный план — отдельный разрез **Тариф**','Биллинг, справочник тарифов','месяц · квартал · год · разовая оплата');
INSERT INTO dimension VALUES(47,'Платформа','Операционная система, на которой работает пользователь. Класс железа — отдельный разрез **Устройство**','Система веб-аналитики, аналитика приложения','iOS · Android · Windows · macOS');
INSERT INTO dimension VALUES(48,'Веб или приложение','Где человек взаимодействует с компанией: в браузере или в её приложении. Независим от **Платформы**: и у iOS, и у Android есть оба','Система веб-аналитики, аналитика приложения','браузер · мобильное приложение');
INSERT INTO dimension VALUES(49,'Стадия сделки','Где сделка находится в воронке продаж','CRM, статус сделки','новый лид · квалифицирован · встреча · КП отправлено · переговоры · закрыта успешно · закрыта отказом');
INSERT INTO dimension VALUES(50,'Причина отказа от сделки','Почему сделка не дошла до продажи. Клиента не по профилю записывают с полем профиля, по которому он не подошёл','CRM, причина закрытия','дорого · выбрали конкурента · нет бюджета · не сезон · не дозвонились · не по профилю: отрасль · не по профилю: размер · не по профилю: задача · не по профилю: география · ушёл без ответа');
INSERT INTO dimension VALUES(51,'Когорта привлечения','Группа клиентов, объединённая моментом первой покупки. Это признак клиента, а не окно наблюдения: когорта у него не меняется от того, за какой период мы смотрим','CRM или учётная система по дате первой покупки','месяц или неделя первой покупки — список открытый и растёт сам');
INSERT INTO dimension VALUES(52,'Сегмент покупателя','Группировка клиентов по признаку, значимому для этой компании. Признак выбирает компания, и он у каждой свой. Кому показывали рекламу — отдельный разрез **Аудитория рекламы**','CRM с собственной разметкой сегментов','Основание открыто: режут по тому, что предсказывает поведение их клиентов — район проживания, поведение, ценовой уровень, RFM. Пол и возраст здесь частный случай, а не обязательный набор');
INSERT INTO dimension VALUES(53,'Тип обращения','С чем клиент пришёл в поддержку','Тикет-система, категория обращения','вопрос по заказу · доставка · возврат и деньги · оплата · технический сбой · жалоба · консультация до покупки');
INSERT INTO dimension VALUES(54,'Канал обращения','Чем клиент обратился. Не путать с **Каналом привлечения** и **Каналом продаж**','Тикет-система, источник обращения','телефон · чат на сайте · почта · мессенджер · соцсети · форма обратной связи · бот');
INSERT INTO dimension VALUES(55,'Бот или оператор','Кто вёл обращение','Тикет-система, признак автоматизации','бот · оператор · начал бот, закрыл оператор');
INSERT INTO dimension VALUES(56,'Должность','Какую работу человек делает. Насколько он опытен — отдельный разрез **Уровень квалификации**','Штатное расписание, кадровый учёт','продавец · курьер · сборщик · оператор поддержки · менеджер по продажам · производственный рабочий · руководитель · бэк-офис');
INSERT INTO dimension VALUES(57,'Уровень квалификации','Насколько человек опытен внутри своей должности','Кадровый учёт, грейдовая сетка','стажёр · младший · средний · старший · ведущий. В рабочих специальностях те же ступени называются разрядом, у специалистов — категорией');
INSERT INTO dimension VALUES(58,'Форма оформления','На каких условиях оформлен человек. Сколько времени он занят — отдельный разрез **Тип занятости**','Кадровый учёт, вид договора','штат · совместительство · подряд или самозанятый · аутстафф · стажёр');
INSERT INTO dimension VALUES(59,'Стаж в компании','Сколько человек проработал','Кадровый учёт, дата приёма','до 3 месяцев · 3–12 месяцев · 1–3 года · больше 3 лет');
INSERT INTO dimension VALUES(60,'Канал найма','Откуда пришёл кандидат','Система подбора, источник отклика','работные сайты · рекомендации сотрудников · агентство · соцсети · карьерная страница · вузы');
INSERT INTO dimension VALUES(61,'Причина увольнения','Почему сотрудник ушёл','Кадровый учёт, основание приказа, выходное интервью','по собственному · не прошёл испытательный · сокращение · инициатива компании · переезд · зарплата · отношения с руководителем');
INSERT INTO dimension VALUES(62,'Этап отбора','На каком шаге подбора находится кандидат','Система подбора, стадия кандидата','отклик · скрининг · интервью с HR · интервью с нанимающим · тестовое · оффер · выход на работу');
INSERT INTO dimension VALUES(63,'ABC-класс товара','Вклад позиции в оборот или прибыль','Расчёт по продажам, разметка в номенклатуре','A · B · C');
INSERT INTO dimension VALUES(64,'Состояние запаса','В каком состоянии лежит остаток','Учёт остатков с расчётом оборачиваемости и сроков','ходовой · медленный · неликвид · недозапас · отсутствует · просрочен');
INSERT INTO dimension VALUES(65,'Вариант товара','Вариативность позиции — уровень ниже **Продукта**','Номенклатурный справочник, характеристики позиции','Основание открыто: признак выбирает компания под свой товар — цвет, размер, объём, вкус, комплектация. Выделять самый частотный нельзя: размер бессмыслен у того, кто продаёт конфеты');
INSERT INTO dimension VALUES(66,'Стадия жизненного цикла товара','На каком этапе жизни находится позиция','Расчёт по дате ввода и динамике продаж','новинка · рост · зрелость · вывод из ассортимента');
INSERT INTO dimension VALUES(67,'Перевозчик','Кто везёт заказ','Реестр перевозчиков, отчёты служб доставки','собственная служба · транспортная компания · служба площадки · курьер на подряде. Конкретные названия свои у каждой компании');
INSERT INTO dimension VALUES(68,'Этап обработки заказа','На каком шаге заказ внутри склада','Складская система, статусы обработки','приём в работу · сборка · упаковка · отгрузка · передача перевозчику');
INSERT INTO dimension VALUES(69,'Причина неуспешной оплаты','Почему платёж не прошёл','Отчёты эквайера и платёжных сервисов, коды отказа','недостаточно средств · отклонён банком · истёк срок карты · не пройдено подтверждение · технический сбой');
INSERT INTO dimension VALUES(70,'Шаг оформления','На каком шаге чекаута находится покупатель','Система веб-аналитики, события чекаута','корзина · контактные данные · доставка · оплата · подтверждение');
INSERT INTO dimension VALUES(71,'Тип промокода','Что за промокод по назначению','Календарь промо, справочник промокодов','общий · индивидуальный · промокод инфлюенсера · приветственный · реактивационный · партнёрский');
INSERT INTO dimension VALUES(72,'Промокод','Конкретный код. Пара к **Типу промокода**, как **Продукт** к **Товарной категории**','Справочник промокодов, отчёт по применениям','Коды, которые выпускает компания. Назначение кода — отдельный разрез **Тип промокода**');
INSERT INTO dimension VALUES(73,'Страница сайта','Конкретная страница, на которой произошло событие. Не путать со **Страницей входа**: та про начало визита','Система веб-аналитики, отчёт по страницам','Адреса страниц сайта. Что это за страница по содержанию — отдельный разрез **Тип страницы**');
INSERT INTO dimension VALUES(74,'Страница выхода','Страница, на которой визит закончился','Система веб-аналитики','Адреса страниц. У визита она ровно одна, как и страница входа, поэтому сумма по сегментам сходится');
INSERT INTO dimension VALUES(75,'Тип страницы','Что это за страница по содержанию','Разметка разделов сайта','главная · каталог · карточка товара · посадочная · статья · корзина · служебная');
INSERT INTO dimension VALUES(76,'Ссылающийся домен','Сайт-донор, с которого стоит ссылка','Сервисы анализа ссылочной массы, отчёт по переходам','Домены, ссылающиеся на наш сайт');
INSERT INTO dimension VALUES(77,'Версия приложения','Сборка приложения, на которой работает пользователь','Аналитика приложения','Номера сборок, которые компания выпускала');
INSERT INTO dimension VALUES(78,'Рекламная кампания','Конкретная кампания в рекламном кабинете','Рекламные кабинеты, UTM-метки','Кампании, заведённые в кабинетах компании');
INSERT INTO dimension VALUES(79,'Рекламное объявление','Конкретный креатив внутри кампании. Пара к **Рекламной кампании**','Рекламные кабинеты','Отдельные объявления и креативы внутри кампаний');
INSERT INTO dimension VALUES(80,'Поисковый запрос','Слово или фраза, по которой показались или пришли из поисковой системы','Search Console, Яндекс Вебмастер, рекламные кабинеты','Фразы, которые люди вводят в поисковой системе');
INSERT INTO dimension VALUES(81,'Запрос внутреннего поиска','Что искали в строке поиска на самом сайте. Отдельно от **Поискового запроса**: другой источник данных','Логи внутреннего поиска','Фразы, которые люди вводят в поиск на сайте');
INSERT INTO dimension VALUES(82,'Балл оценки','Какую оценку поставили','Отзывы в сторах и на площадках, опросы','1 · 2 · 3 · 4 · 5');
INSERT INTO dimension VALUES(83,'Формат контента','Чем сделан материал. Не путать с **Видом материала**: тот про закупаемое сырьё','Контент-план, разметка материалов','текст · фото · видео · карусель · сторис · инфографика · вебинар · подкаст');
INSERT INTO dimension VALUES(84,'Тема контента','О чём материал','Контент-план, рубрикатор','Рубрики контент-плана, набор свой у каждой компании');
INSERT INTO dimension VALUES(85,'Тип письма','Зачем отправлено письмо','Платформа рассылок, тип кампании','регулярная рассылка · триггерное · транзакционное · реактивационное · анонс');
INSERT INTO dimension VALUES(86,'Причина недоставки','Почему письмо не дошло до адресата','Платформа рассылок, коды отказа','несуществующий адрес · переполнен ящик · спам-фильтр · блокировка домена · временный отказ сервера');
INSERT INTO dimension VALUES(87,'Причина отписки','Почему подписчик отписался от рассылки','Платформа рассылок, форма отписки','слишком часто пишут · неинтересно · не подписывался · нашёл в спаме · вопрос решён');
INSERT INTO dimension VALUES(88,'Причина отмены подписки','Почему клиент отказался от платной подписки','Биллинг, форма отмены, опрос при отказе','дорого · не пользуюсь · нашёл замену · разовая задача закрыта · не хватило функций · технические проблемы');
INSERT INTO dimension VALUES(89,'Тип целевого действия','Какое именно целевое действие совершил посетитель','Система веб-аналитики, настройка целей','заявка с формы · звонок · заказ обратного звонка · подписка · скачивание · сообщение в чат');
INSERT INTO dimension VALUES(90,'Маркетплейс','Конкретная торговая площадка. Пара к **Каналу продаж** — там, где разбор по каналу слишком крупный','Кабинеты площадок','Wildberries · Ozon · Яндекс Маркет · Мегамаркет и другие');
INSERT INTO dimension VALUES(91,'Схема работы с маркетплейсом','Кто хранит товар и кто его отгружает','Кабинет площадки, договор','со склада маркетплейса · со своего склада с доставкой маркетплейса · со своего склада своей доставкой · витрина без хранения');
INSERT INTO dimension VALUES(92,'Инфлюенсер','Конкретный блогер или партнёр по размещению','Реестр размещений, договоры','Блогеры и партнёры, с которыми были размещения');
INSERT INTO dimension VALUES(93,'Размер аудитории','Насколько крупный блогер по числу подписчиков','Данные площадки, медиакит','нано · микро · макро · мега. Границы каждая компания задаёт свои');
INSERT INTO dimension VALUES(94,'Уровень программы лояльности','На какой ступени программы находится участник','Система лояльности','базовый · средний · высший. Названия свои у каждой программы');
INSERT INTO dimension VALUES(95,'Повод начисления бонусов','За что начислены бонусы. Не «причина»: начисление — событие, а не поломка','Система лояльности, правила начисления','покупка · регистрация · отзыв · приглашение друга · компенсация · день рождения · акция');
INSERT INTO dimension VALUES(96,'Этап онбординга','На каком шаге знакомства с продуктом находится пользователь','Продуктовая аналитика, воронка онбординга','регистрация · первое действие · ключевое действие · привычка. Список свой у каждого продукта');
INSERT INTO dimension VALUES(97,'Поток обучения','Конкретный набор студентов','Учебная платформа, реестр потоков','Потоки, которые компания запускала');
INSERT INTO dimension VALUES(98,'Модуль курса','Часть программы, на которой смотрят прохождение','Учебная платформа, структура курса','Части программы конкретного курса');
INSERT INTO dimension VALUES(99,'Тип занятости','Сколько времени человек занят: полный день, неполная ставка, сменный график. На каких условиях он оформлен — отдельный разрез **Форма оформления**','Кадровый учёт, условия трудового договора','полная · частичная · сменный график · вахта · стажировка');
INSERT INTO dimension VALUES(100,'Аудитория рекламы','Кому кампания показывалась: интересы, look-alike, ретаргетинг, загруженный список, соцдем. Не путать с **Сегментом покупателя**: тот про признак человека в нашей базе','Рекламный кабинет, настройки таргетинга','интересы · look-alike · ретаргетинг · загруженный список · соцдем · широкая');
INSERT INTO dimension VALUES(101,'Ключевая фраза','Фраза, купленная в рекламном кабинете. Пара к **Поисковому запросу**: фраза это то, что купили и на что ставят ставку, запрос — то, что человек реально набрал','Рекламные кабинеты','Ключевые фразы, заведённые в группах объявлений');
INSERT INTO dimension VALUES(102,'Площадка размещения','Соцсеть, видеосервис или мессенджер, где вышло размещение. Правила публикации, набор доступных реакций, доступность ссылки и состав отдаваемой статистики там разные. Не путать с **Платформой**: та про операционную систему пользователя','Реестр размещений, статистика площадки','Соцсети, видеосервисы, мессенджеры и блог-платформы, где работают блогеры');
INSERT INTO dimension VALUES(103,'Способ распространения ссылки','Как рекомендатель передал реферальную ссылку: мессенджер, соцсеть, почта, копирование вручную. Задаётся кнопками «поделиться» и меткой в самой ссылке. Не путать с **Каналом привлечения**: для реферальной программы он у всех приглашённых один и тот же — рекомендации','Реферальный сервис, метка способа шеринга в ссылке','мессенджер · соцсеть · почта · копирование ссылки вручную · QR-код');
INSERT INTO dimension VALUES(104,'Бесплатная или платная доставка','Платил ли покупатель за доставку заказа. Бесплатной доставка бывает от порога суммы заказа, по акции или по подписке. Самовывоз из магазина сюда не входит: доставки у него нет','Учётная система, плата за доставку в заказе','бесплатная · платная');
INSERT INTO dimension VALUES(105,'Функция продукта','Возможность продукта, которой пользуется клиент: отчёты, выгрузки, интеграции, совместная работа. Не путать с **Вариантом товара**: вариант выбирают при покупке, а функцией пользуются внутри купленного продукта','Продуктовая аналитика, события использования функций','Функции, которые компания отслеживает в продуктовой аналитике. Список свой у каждого продукта');
INSERT INTO dimension VALUES(106,'Канал рассылки','Чем компания сама пишет клиенту: письмо, пуш, мессенджер, СМС. Не путать с **Каналом обращения**: тот про то, чем клиент обратился к компании','Платформа рассылок, CRM','письмо · пуш · мессенджер · СМС');
INSERT INTO dimension VALUES(107,'Участник программы лояльности или нет','Состоит ли покупатель в программе лояльности. Ступень внутри программы — отдельный разрез **Уровень программы лояльности**','Система лояльности, CRM','участник · не участник');
INSERT INTO dimension VALUES(108,'Давность последней покупки','Сколько времени прошло с последней покупки клиента: ось R из RFM. Группа на пересечении осей RFM — **Сегмент покупателя**; сколько раз клиент покупал — **Число покупок клиента**. Для долей клиентов признак берут на начало периода, иначе покупка периода сама переносит клиента в соседнюю группу','CRM или учётная система по дате последней покупки','интервалы в днях или месяцах: до месяца · 1–2 месяца · 3–5 месяцев · полгода–год · больше года. Границы каждая компания задаёт по своему циклу покупки');
INSERT INTO dimension VALUES(109,'Число покупок клиента','Сколько раз клиент покупал за всю историю: ось F из RFM. Первая покупка против всех следующих — более грубое деление, отдельный разрез **Новый или повторный**. Для долей клиентов признак берут на начало периода','CRM или учётная система по истории покупок','1 · 2 · 3–5 · 6 и больше. Границы свои у каждой компании');
INSERT INTO metric_dimension VALUES(1,746,1,1,'увидеть, из чего собраны доходы');
INSERT INTO metric_dimension VALUES(2,746,2,2,'сравнить доходы между направлениями бизнеса');
INSERT INTO metric_dimension VALUES(3,907,1,1,'увидеть, из чего собраны прочие доходы');
INSERT INTO metric_dimension VALUES(4,907,24,2,'увидеть, какой объект приносит доход, а какая часть статьи к объектам не относится');
INSERT INTO metric_dimension VALUES(5,907,17,3,'увидеть, на каких условиях приходит доход от каждого источника');
INSERT INTO metric_dimension VALUES(6,907,2,4,'увидеть, какое направление владеет активами, дающими доход');
INSERT INTO metric_dimension VALUES(7,748,17,1,'увидеть, от кого пришли разовые поступления');
INSERT INTO metric_dimension VALUES(8,748,2,2,'увидеть, какое направление породило разовые поступления');
INSERT INTO metric_dimension VALUES(9,749,17,1,'увидеть, какая доля в других компаниях приносит доход');
INSERT INTO metric_dimension VALUES(10,750,20,1,'сравнить курсовой доход между валютами');
INSERT INTO metric_dimension VALUES(11,750,17,2,'увидеть, по каким обязательствам возник курсовой доход');
INSERT INTO metric_dimension VALUES(12,751,17,1,'выявить поставщиков, по которым долги списываются регулярно');
INSERT INTO metric_dimension VALUES(13,752,44,1,'увидеть, за какие нарушения получены неустойки');
INSERT INTO metric_dimension VALUES(14,752,17,2,'выявить контрагентов, с которых неустойки идут регулярно');
INSERT INTO metric_dimension VALUES(15,753,24,1,'увидеть, какие объекты проданы и с каким результатом');
INSERT INTO metric_dimension VALUES(16,754,17,1,'выявить поставщиков, у которых бонус не добирается');
INSERT INTO metric_dimension VALUES(17,754,7,2,'выявить категории, в которых бонус заметно меняет закупочную цену');
INSERT INTO metric_dimension VALUES(18,755,21,1,'сравнить ставку между сроками размещения');
INSERT INTO metric_dimension VALUES(19,755,17,2,'сравнить ставку между банками и заёмщиками');
INSERT INTO metric_dimension VALUES(20,756,24,1,'увидеть, сколько приносит каждый объект в аренде');
INSERT INTO metric_dimension VALUES(21,756,17,2,'выявить арендаторов со сравнительно низким вкладом');
INSERT INTO metric_dimension VALUES(31,670,40,1,'увидеть, из каких причин собран возвратный поток');
INSERT INTO metric_dimension VALUES(32,670,7,2,'выявить категории, дающие основную часть возвратов');
INSERT INTO metric_dimension VALUES(33,670,5,5,'сравнить число возвратов между каналами продаж');
INSERT INTO metric_dimension VALUES(34,670,12,6,'выявить регионы с высоким числом возвратов');
INSERT INTO metric_dimension VALUES(35,670,8,7,'сравнить число возвратов у новых и у повторных покупателей');
INSERT INTO metric_dimension VALUES(36,670,17,8,'выявить поставщиков, товар которых возвращают чаще');
INSERT INTO metric_dimension VALUES(72,635,6,1,'выявить каналы, дающие мало прироста платящих');
INSERT INTO metric_dimension VALUES(74,635,10,3,'сравнить прирост платящих у юрлиц и у частных пользователей');
INSERT INTO metric_dimension VALUES(75,635,11,4,'выявить отрасли, в которых база не растёт');
INSERT INTO metric_dimension VALUES(76,635,12,5,'выявить регионы, в которых база не растёт');
INSERT INTO metric_dimension VALUES(77,620,6,1,'выявить каналы, из которых до оплаты не доходят');
INSERT INTO metric_dimension VALUES(79,620,10,2,'сравнить долю дошедших до оплаты у юрлиц и у частных пользователей');
INSERT INTO metric_dimension VALUES(80,620,11,3,'выявить отрасли, в которых продукт бросают после пробы');
INSERT INTO metric_dimension VALUES(81,620,12,4,'выявить регионы, в которых продукт пробуют, но не покупают');
INSERT INTO metric_dimension VALUES(88,542,15,1,'выявить менеджеров, у которых сделки идут дольше');
INSERT INTO metric_dimension VALUES(89,542,9,2,'увидеть, у клиентов какого размера цикл длиннее');
INSERT INTO metric_dimension VALUES(90,542,8,3,'сравнить цикл сделки с новыми компаниями и с действующими клиентами');
INSERT INTO metric_dimension VALUES(91,542,6,4,'выявить каналы, из которых сделки закрываются дольше');
INSERT INTO metric_dimension VALUES(92,542,16,5,'выявить конкретные сделки, которые стоят дольше остальных');
INSERT INTO metric_dimension VALUES(93,537,6,1,'выявить каналы со сравнительно низкой сквозной конверсией');
INSERT INTO metric_dimension VALUES(94,537,15,2,'выявить менеджеров с низкой сквозной конверсией');
INSERT INTO metric_dimension VALUES(95,537,8,3,'сравнить сквозную конверсию у новых компаний и у действующих клиентов');
INSERT INTO metric_dimension VALUES(96,537,10,4,'сравнить сквозную конверсию у юрлиц и физлиц');
INSERT INTO metric_dimension VALUES(97,537,11,5,'выявить отрасли с низкой сквозной конверсией');
