INSERT INTO metric_dimension VALUES(4865,965,13,7,'выявить команды, в которых сравнительно большая часть квалифицированных и записанных на встречу клиентов оказывается не по профилю');
INSERT INTO metric_dimension VALUES(4866,965,8,8,'выявить, новые компании или действующие клиенты сравнительно чаще оказываются на встрече не по профилю');
INSERT INTO metric_dimension VALUES(4867,966,15,1,'выявить менеджеров, после КП которых с клиентом сравнительно редко связываются в первые дни');
INSERT INTO metric_dimension VALUES(4868,966,9,2,'сравнить КП компаниям разного размера и выявить размер, при котором после КП с клиентом сравнительно редко связываются');
INSERT INTO metric_dimension VALUES(4869,966,25,3,'выявить продукты, КП по которым сравнительно редко обсуждают с клиентом в первые дни после отправки');
INSERT INTO metric_dimension VALUES(4870,966,13,4,'выявить команды, в которых после отправки КП сравнительно редко сами выходят на связь с клиентом');
INSERT INTO metric_dimension VALUES(4871,966,11,5,'выявить отрасли клиентов, с которыми после КП сравнительно редко связываются');
INSERT INTO metric_dimension VALUES(4872,966,6,6,'выявить каналы, по заявкам из которых КП сравнительно часто остаётся без касания');
INSERT INTO metric_dimension VALUES(4873,966,36,7,'сравнить дни недели, в которые отправили КП, и выявить дни отправки, после которых с клиентом сравнительно редко связываются в отведённый срок');
INSERT INTO metric_dimension VALUES(4874,966,38,8,'выявить площадки внутри канала со сравнительно низкой долей КП, после которых с клиентом связались');
INSERT INTO metric_dimension VALUES(4875,966,12,9,'выявить территории клиентов, после КП которым сравнительно редко выходят на связь');
INSERT INTO metric_dimension VALUES(4876,966,8,10,'сравнить КП новым компаниям и действующим клиентам и выявить, после каких с клиентом сравнительно реже связываются');
INSERT INTO metric_dimension VALUES(4877,966,10,11,'выявить среди юрлиц, ИП и физлиц тип клиента, КП которому сравнительно часто остаётся без касания');
INSERT INTO metric_dimension VALUES(4878,966,35,12,'сравнить КП, отправленные в разные месяцы года, и выявить месяцы, в которые они сравнительно часто остаются без касания');
INSERT INTO metric_dimension VALUES(4879,967,15,1,'выявить менеджеров, которые в первой версии своих КП сравнительно сильно снижают цену против прайса');
INSERT INTO metric_dimension VALUES(4880,967,9,2,'выявить размер клиентов, которым в первой версии КП уступают сравнительно большую часть цены по прайсу');
INSERT INTO metric_dimension VALUES(4881,967,16,3,'увидеть, на каких отдельных КП держится скидка в рублях, и выявить КП со сравнительно глубокой скидкой');
INSERT INTO metric_dimension VALUES(4882,967,25,4,'выявить позиции прайса, цену которых в первой версии КП сравнительно сильно снижают; скидку строкой на всё КП разрез видит, только если её разнесли по позициям');
INSERT INTO metric_dimension VALUES(4883,967,7,5,'выявить группы товаров и услуг, на которые в первых версиях КП приходится сравнительно глубокая скидка; скидка строкой на всё КП попадает в группы, только если её разнесли по позициям');
INSERT INTO metric_dimension VALUES(4884,967,13,6,'выявить команды со сравнительно глубокой скидкой в первой версии КП');
INSERT INTO metric_dimension VALUES(4885,967,8,7,'сравнить скидку в первом предложении новым компаниям и действующим клиентам и выявить, кому уступают сравнительно больше');
INSERT INTO metric_dimension VALUES(4886,967,11,8,'выявить отрасли, клиентам из которых первое предложение делают со сравнительно глубокой скидкой');
INSERT INTO metric_dimension VALUES(4887,967,6,9,'выявить каналы, по заявкам из которых первая версия КП выходит сравнительно сильно ниже прайса');
INSERT INTO metric_dimension VALUES(4888,967,38,10,'выявить площадки внутри канала, по лидам с которых в первой версии КП уступают сравнительно большую часть цены');
INSERT INTO metric_dimension VALUES(4889,967,12,11,'выявить территории клиентов, которым в первой версии КП дают сравнительно глубокую скидку');
INSERT INTO metric_dimension VALUES(4890,967,35,12,'сравнить первые версии КП, отправленные в разные месяцы года, и выявить месяцы со сравнительно глубокой скидкой');
