PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE artifact (
  id       INTEGER PRIMARY KEY,
  type     TEXT NOT NULL CHECK (type IN ('map','tree')),
  name     TEXT NOT NULL UNIQUE,
  slug     TEXT NOT NULL UNIQUE,
  access   TEXT CHECK (access IN ('free','paid')),
  status   TEXT,
  purpose  TEXT
, family_id INTEGER REFERENCES family(id));
CREATE TABLE metric_artifact (
  id          INTEGER PRIMARY KEY,
  metric_id   INTEGER NOT NULL REFERENCES metric(id)   ON DELETE CASCADE,
  artifact_id INTEGER NOT NULL REFERENCES artifact(id) ON DELETE CASCADE,
  -- вечный идентификатор узла, каким он ушёл в бой: на нём держатся ссылки
  -- в контенте, metric_ids.json и накопленная статистика Метрики. Не вычисляется
  -- из slug: slug карты менялся, node_id остаётся прежним
  node_id     TEXT UNIQUE,
  x REAL, y REAL, w REAL, h REAL,
  "group"     TEXT,
  is_key      INTEGER DEFAULT 0, role TEXT
                  CHECK (role IN ('result','cost','action','diagnostic',
                                  'key','component','driver')), label_dimension_id INTEGER REFERENCES dimension(id), label_value TEXT, label_text TEXT, question TEXT,
  UNIQUE (metric_id, artifact_id)
);
CREATE TABLE dimension (
  id          INTEGER PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  description TEXT,
  source      TEXT
, variants TEXT);
CREATE TABLE metric_dimension (
  id           INTEGER PRIMARY KEY,
  metric_id    INTEGER NOT NULL REFERENCES metric(id)    ON DELETE CASCADE,
  dimension_id INTEGER NOT NULL REFERENCES dimension(id) ON DELETE CASCADE,
  priority     INTEGER,
  note         TEXT,
  UNIQUE (metric_id, dimension_id)
);
CREATE TABLE family (
  id     INTEGER PRIMARY KEY,
  key    TEXT NOT NULL UNIQUE,
  name   TEXT NOT NULL UNIQUE,
  accent TEXT,
  blurb  TEXT,
  sort   INTEGER NOT NULL
);
CREATE TABLE metric_map (
  id       INTEGER PRIMARY KEY,
  place_id    INTEGER NOT NULL REFERENCES metric_artifact(id) ON DELETE CASCADE,
  artifact_id INTEGER NOT NULL REFERENCES artifact(id)        ON DELETE CASCADE,
  comment  TEXT,
  UNIQUE (place_id, artifact_id)
);
CREATE TABLE IF NOT EXISTS "metric_metric" (
  id        INTEGER PRIMARY KEY,
  source_id INTEGER NOT NULL REFERENCES metric_artifact(id) ON DELETE CASCADE,
  target_id INTEGER NOT NULL REFERENCES metric_artifact(id) ON DELETE CASCADE,
  type      TEXT NOT NULL CHECK (type IN ('influence','arithmetic','associative','similarity')),
  sign      TEXT CHECK (sign IN ('+','-')),
  points    TEXT,
  style     TEXT CHECK (style IN ('solid','dashed')),
  comment   TEXT
);
CREATE TABLE IF NOT EXISTS "metric" (
      id          INTEGER PRIMARY KEY,
      name        TEXT NOT NULL,
      slug        TEXT NOT NULL,
      unit        TEXT CHECK (unit IN ('Количество','%','Деньги','Время')),
      formula     TEXT,
      alt_formula TEXT,
      description TEXT,
      nuances     TEXT,
      example     TEXT,
      importance  TEXT,
      not_needed  TEXT,
      en          TEXT,
      synonyms    TEXT
    , essence TEXT
  CHECK (essence IN ('больше-лучше','меньше-лучше','баланс')), essence_note TEXT);
CREATE TABLE question (
  id        INTEGER PRIMARY KEY,
  metric_id INTEGER NOT NULL REFERENCES metric(id) ON DELETE CASCADE,
  priority  INTEGER,
  text      TEXT NOT NULL,
  answer    TEXT
, group_id TEXT REFERENCES question_group(id));
CREATE TABLE question_dimension (
  id           INTEGER PRIMARY KEY,
  question_id  INTEGER NOT NULL REFERENCES question(id)  ON DELETE CASCADE,
  dimension_id INTEGER NOT NULL REFERENCES dimension(id) ON DELETE CASCADE,
  UNIQUE (question_id, dimension_id)
);
CREATE TABLE question_group (
                     id    TEXT PRIMARY KEY,
                     name  TEXT NOT NULL,
                     hint  TEXT NOT NULL,
                     sort  INTEGER NOT NULL);
CREATE TABLE question_base (
                     id       INTEGER PRIMARY KEY,
                     priority INTEGER NOT NULL,
                     text     TEXT NOT NULL);
CREATE INDEX idx_ma_metric   ON metric_artifact(metric_id);
CREATE INDEX idx_ma_artifact ON metric_artifact(artifact_id);
CREATE INDEX idx_q_metric ON question(metric_id);
CREATE INDEX idx_qd_question ON question_dimension(question_id);
CREATE INDEX idx_metric_artifact_label
                   on metric_artifact(label_dimension_id, label_value);
COMMIT;
